    conversations() {
      const teams = this.$teams.teams || []
      const list = []
      teams.forEach(team => {
        (team.categories || []).forEach(cat => {
          (cat.channels || []).forEach(ch => {
            list.push({ id: `${team.id}-${ch.id}`, name: `# ${ch.name}`, team: team.name })
