          {{ file.path }}
        </li>
      </ul>
    </div>

    <!-- Changed files -->
    <div v-else-if="attachment.type === 'code'" class="p-3">
      <div class="text-xs text-base-content/50 mb-2">
        <i class="fa-solid fa-code"></i> {{ attachment.files.length }} file(s)
      </div>
      <ul class="divide-y divide-base-content/10">
